var fsCache=null,fsAberto=null,fsFotos=[],fsSlot=0;
var FS_ROT=['Frente','Verso','Código / detalhe'];
function irFS(){
  pararCamera();$('faixaFS').textContent='FOTOS DO SITE · '+quem;mostrar('tFS');
  try{fsCache=JSON.parse(localStorage.getItem('ci_fs')||'null');}catch(e){}
  renderFS();carregarFS();
}
function carregarFS(){
  api({acao:'fotosSite',quem:quem}).then(function(r){if(r&&r.ok){fsCache=r.itens||[];try{localStorage.setItem('ci_fs',JSON.stringify(fsCache));}catch(e){}renderFS();}else if(r&&r.erro){toast(r.erro,'err');}}).catch(function(){});
}
function renderFS(){
  var box=$('fsLista');box.innerHTML='';
  if(!fsCache){box.innerHTML='<p class="dica">Carregando…</p>';return;}
  if(!fsCache.length){box.innerHTML='<p class="dica" style="font-size:16px;margin-top:20px">Nenhum produto esperando foto. 👍</p>';$('fsProg').textContent='';return;}
  var env=fsCache.filter(function(i){return i.status==='ENVIADO';}).length;
  $('fsProg').textContent=env+' / '+fsCache.length+' enviados';
  var ordem=[['A FOTOGRAFAR',function(i){return i.status!=='ENVIADO';}],['JÁ ENVIADOS',function(i){return i.status==='ENVIADO';}]];
  ordem.forEach(function(o){
    var its=fsCache.filter(o[1]);if(!its.length)return;
    var hd=document.createElement('div');hd.className='grp';hd.textContent=o[0]+' ('+its.length+')';box.appendChild(hd);
    var ul=document.createElement('ul');ul.className='fs';
    its.forEach(function(it){
      var li=document.createElement('li');li.className=it.status==='ENVIADO'?'env':(it.status==='REFAZER'?'ref':'');
      var html='<div class="d">'+esc(it.desc)+'</div><div class="m">SKU '+esc(it.sku)+(it.secao?' · '+esc(it.secao):'')+'</div>';
      if(it.status==='REFAZER')html+='<div class="m" style="color:#b91c1c;font-weight:700">Tirar de novo'+(it.obs?': '+esc(it.obs):'')+'</div>';
      if(it.status==='ENVIADO')html+='<div class="m" style="color:#15803d;font-weight:700">✅ '+(it.fotos||'')+(it.fotos===1?' foto enviada':' fotos enviadas')+(it.quem?' · '+esc(it.quem):'')+(it.em?' · '+esc(it.em):'')+'</div>';
      if(fsAberto===it.sku){
        html+='<div class="fsSlots">';
        for(var k=0;k<3;k++){html+='<button class="fsSlot'+(fsFotos[k]?' ok':'')+'" data-k="'+k+'">'+(fsFotos[k]?'<img src="'+fsFotos[k]+'">':'<span style="font-size:26px">📷</span>')+(fsFotos[k]?'✅ ':'')+FS_ROT[k]+(k===0?' *':'')+'</button>';}
        html+='</div><div class="m">* a foto da frente é obrigatória; as outras ajudam</div>';
        html+='<button class="bt env">ENVIAR FOTOS</button><button class="bt sec can">Cancelar</button>';
      }else{
        html+='<button class="bt'+(it.status==='ENVIADO'?' sec':'')+' abre">'+(it.status==='ENVIADO'?'Mandar de novo':'📷 FOTOGRAFAR')+'</button>';
      }
      li.innerHTML=html;
      var ab=li.querySelector('.abre');if(ab)ab.onclick=function(){vibra();fsAberto=it.sku;fsFotos=[];renderFS();};
      var cn=li.querySelector('.can');if(cn)cn.onclick=function(){fsAberto=null;fsFotos=[];renderFS();};
      var ev=li.querySelector('.env');if(ev)ev.onclick=function(){enviarFS(it,ev);};
      li.querySelectorAll('.fsSlot').forEach(function(b){b.onclick=function(){fsSlot=+b.getAttribute('data-k');$('fsFile').click();};});
      ul.appendChild(li);
    });
    box.appendChild(ul);
  });
}
$('fsFile').addEventListener('change',function(){
  var inp=this,f=inp.files[0];if(!f)return;inp.value='';
  toast('Preparando foto…');
  var img=new Image();img.onload=function(){
    var MAX=1600,w=img.width,h=img.height,k=Math.min(1,MAX/Math.max(w,h));
    var c=document.createElement('canvas');c.width=Math.round(w*k);c.height=Math.round(h*k);
    c.getContext('2d').drawImage(img,0,0,c.width,c.height);
    fsFotos[fsSlot]=c.toDataURL('image/jpeg',0.85);URL.revokeObjectURL(img.src);renderFS();
  };img.onerror=function(){toast('Não deu para ler a foto','err');};img.src=URL.createObjectURL(f);
});
function enviarFS(it,bt){
  if(!fsFotos[0]){toast('Tire a foto da frente','err');return;}
  var fotos=fsFotos.filter(Boolean);
  bt.disabled=true;bt.textContent='Enviando…';
  api({acao:'salvarFotosSite',quem:quem,token:token,sku:it.sku,fotos:fotos}).then(function(r){
    if(r&&r.ok){vibra();it.status='ENVIADO';it.quem=quem;it.em='agora';it.fotos=r.fotos||fotos.length;fsAberto=null;fsFotos=[];try{localStorage.setItem('ci_fs',JSON.stringify(fsCache));}catch(e){}toast('Fotos enviadas ✅');renderFS();return;}
    bt.disabled=false;bt.textContent='ENVIAR FOTOS';if(r&&r.reauth){irPin();return;}toast((r&&r.erro)||'Não enviou','err');
  }).catch(function(){bt.disabled=false;bt.textContent='ENVIAR FOTOS';toast('Sem conexão. Tente de novo.','err');});
}

